function testGetOption() {
  console.log(getOption(["--crop", "Kale"], "--crop"))
  console.log(getOption(["--crop"], "--crop"))
  console.log(getOption(["--from", "2027-06-01"], "--crop"))
}

function getOption(args, name) {
  const index = args.indexOf(name)
  if (index === -1 || index + 1 >= args.length) {
    return null
  }
  return args[index + 1]
}
